from pathlib import Path
import json,statistics
p=Path(__file__).parent
all_summaries={}
for mode in ['default','fixed','native']:
 d=json.loads((p/f'performance-{mode}.json').read_text());cases={}
 for case in d['cases']:
  variants={}
  for v in ['before','after']:
   runs=[r for r in d['runs'] if r['case']==case and r['variant']==v]
   medians=[r['median_ms'] for r in runs]
   counters={event:statistics.median(float(next(c['counter-value'] for c in r['counters'] if c['event']==event)) for r in runs) for event in ['instructions:u','cycles:u','page-faults:u']}
   groups={name:[r['median_ms'] for r in runs if (r['page_faults']<1000)==low] for name,low in [('low_fault',True),('high_fault',False)]}
   variants[v]={'processes':len(runs),'median_ms':statistics.median(medians),'mean_ms':statistics.mean(medians),'range_ms':[min(medians),max(medians)],'faults_range':[min(r['page_faults'] for r in runs),max(r['page_faults'] for r in runs)],'median_counters':counters,'groups':{k:{'processes':len(values),'median_ms':statistics.median(values) if values else None} for k,values in groups.items()}}
  variants['change_percent']={key:(variants['after'][key]/variants['before'][key]-1)*100 for key in ['median_ms','mean_ms']}
  cases[case]=variants
  print(mode,case,round(variants['before']['median_ms'],3),round(variants['after']['median_ms'],3),round(variants['change_percent']['median_ms'],2),variants['after']['faults_range'])
 all_summaries[mode]=cases
(p/'performance-summary.json').write_text(json.dumps(all_summaries,indent=2)+'\n')
